create type public.app_role as enum ('admin');
create table public.user_roles (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade not null, role public.app_role not null, unique(user_id,role));
grant select on public.user_roles to authenticated; grant all on public.user_roles to service_role;
alter table public.user_roles enable row level security;
create function public.has_role(_user_id uuid,_role public.app_role) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_roles where user_id=_user_id and role=_role) $$;
revoke all on function public.has_role(uuid,public.app_role) from public; grant execute on function public.has_role(uuid,public.app_role) to authenticated;
create policy role_read on public.user_roles for select to authenticated using(user_id=auth.uid() or public.has_role(auth.uid(),'admin'));
create table public.brands(id uuid primary key default gen_random_uuid(),name text not null unique);
grant select,insert,update,delete on public.brands to authenticated; grant all on public.brands to service_role;
alter table public.brands enable row level security;
create policy brands_admin on public.brands for all to authenticated using(public.has_role(auth.uid(),'admin')) with check(public.has_role(auth.uid(),'admin'));
create table public.categories(id uuid primary key default gen_random_uuid(),name text not null unique);
grant select,insert,update,delete on public.categories to authenticated; grant all on public.categories to service_role;
alter table public.categories enable row level security;
create policy categories_admin on public.categories for all to authenticated using(public.has_role(auth.uid(),'admin')) with check(public.has_role(auth.uid(),'admin'));
create table public.products(id uuid primary key default gen_random_uuid(),name text not null,sku text not null unique,brand_id uuid references public.brands(id),category_id uuid references public.categories(id),size text not null default 'M',color text not null default 'Black',price numeric(12,2) not null default 0 check(price>=0),stock integer not null default 0 check(stock>=0),low_stock integer not null default 5 check(low_stock>=0),created_at timestamptz not null default now());
grant select,insert,update,delete on public.products to authenticated; grant all on public.products to service_role;
alter table public.products enable row level security;
create policy products_admin on public.products for all to authenticated using(public.has_role(auth.uid(),'admin')) with check(public.has_role(auth.uid(),'admin'));
create table public.invoices(id uuid primary key default gen_random_uuid(),number bigint generated always as identity unique,customer text not null default 'Walk-in customer',payment text not null default 'Cash',status text not null default 'paid' check(status in ('paid','cancelled')),total numeric(12,2) not null default 0,created_at timestamptz not null default now());
grant select on public.invoices to authenticated; grant all on public.invoices to service_role;
alter table public.invoices enable row level security;
create policy invoices_admin_read on public.invoices for select to authenticated using(public.has_role(auth.uid(),'admin'));
create table public.invoice_items(id uuid primary key default gen_random_uuid(),invoice_id uuid not null references public.invoices(id) on delete cascade,product_id uuid not null references public.products(id),name text not null,quantity integer not null check(quantity>0),price numeric(12,2) not null check(price>=0));
grant select on public.invoice_items to authenticated; grant all on public.invoice_items to service_role;
alter table public.invoice_items enable row level security;
create policy items_admin_read on public.invoice_items for select to authenticated using(public.has_role(auth.uid(),'admin'));
create table public.stock_movements(id uuid primary key default gen_random_uuid(),product_id uuid references public.products(id) on delete set null,product_name text not null,change integer not null,note text not null,created_at timestamptz not null default now());
grant select on public.stock_movements to authenticated; grant all on public.stock_movements to service_role;
alter table public.stock_movements enable row level security;
create policy movements_admin_read on public.stock_movements for select to authenticated using(public.has_role(auth.uid(),'admin'));
create function public.adjust_stock(p_id uuid,p_change integer,p_note text) returns void language plpgsql security definer set search_path=public as $$ declare p public.products; begin if not public.has_role(auth.uid(),'admin') then raise exception 'Admin access required'; end if; select * into p from public.products where id=p_id for update; if not found then raise exception 'Product not found'; end if; if p.stock+p_change<0 then raise exception 'Insufficient stock'; end if; update public.products set stock=stock+p_change where id=p_id; insert into public.stock_movements(product_id,product_name,change,note) values(p_id,p.name,p_change,p_note); end $$;
create function public.save_invoice(p_customer text,p_payment text,p_items jsonb,p_id uuid default null) returns uuid language plpgsql security definer set search_path=public as $$ declare inv uuid; item jsonb; p public.products; olditem public.invoice_items; qty integer; cost numeric; total_cost numeric=0; begin if not public.has_role(auth.uid(),'admin') then raise exception 'Admin access required'; end if; if jsonb_array_length(p_items)=0 then raise exception 'Add at least one product'; end if; if p_id is not null then perform 1 from public.invoices where id=p_id and status='paid' for update; if not found then raise exception 'Invoice cannot be edited'; end if; end if; perform id from public.products where id in (select (value->>'product_id')::uuid from jsonb_array_elements(p_items) union select product_id from public.invoice_items where invoice_id=p_id) order by id for update;
if p_id is not null then for olditem in select * from public.invoice_items where invoice_id=p_id loop update public.products set stock=stock+olditem.quantity where id=olditem.product_id; insert into public.stock_movements(product_id,product_name,change,note) values(olditem.product_id,olditem.name,olditem.quantity,'Invoice edit reversal'); end loop; delete from public.invoice_items where invoice_id=p_id; inv=p_id; else insert into public.invoices(customer,payment) values(p_customer,p_payment) returning id into inv; end if;
for item in select * from jsonb_array_elements(p_items) loop qty=(item->>'quantity')::integer; cost=(item->>'price')::numeric; if qty is null or qty<=0 or cost is null or cost<0 then raise exception 'Invalid quantity or price'; end if; select * into p from public.products where id=(item->>'product_id')::uuid; if not found or p.stock<qty then raise exception 'Insufficient stock'; end if; update public.products set stock=stock-qty where id=p.id; insert into public.invoice_items(invoice_id,product_id,name,quantity,price) values(inv,p.id,p.name,qty,cost); insert into public.stock_movements(product_id,product_name,change,note) values(p.id,p.name,-qty,'Invoice sale'); total_cost=total_cost+qty*cost; end loop; update public.invoices set customer=p_customer,payment=p_payment,total=total_cost where id=inv; return inv; end $$;
create function public.cancel_invoice(p_id uuid,p_delete boolean default false) returns void language plpgsql security definer set search_path=public as $$ declare inv public.invoices; item public.invoice_items; begin if not public.has_role(auth.uid(),'admin') then raise exception 'Admin access required'; end if; select * into inv from public.invoices where id=p_id for update; if not found then raise exception 'Invoice not found'; end if; if inv.status='paid' then perform id from public.products where id in(select product_id from public.invoice_items where invoice_id=p_id) order by id for update; for item in select * from public.invoice_items where invoice_id=p_id loop update public.products set stock=stock+item.quantity where id=item.product_id; insert into public.stock_movements(product_id,product_name,change,note) values(item.product_id,item.name,item.quantity,'Invoice cancelled'); end loop; end if; if p_delete then delete from public.invoices where id=p_id; else update public.invoices set status='cancelled' where id=p_id; end if; end $$;
revoke all on function public.adjust_stock(uuid,integer,text),public.save_invoice(text,text,jsonb,uuid),public.cancel_invoice(uuid,boolean) from public;
grant execute on function public.adjust_stock(uuid,integer,text),public.save_invoice(text,text,jsonb,uuid),public.cancel_invoice(uuid,boolean) to authenticated;